import { useState } from 'react';
import axios from 'axios';

function App() {
  const [code, setCode] = useState('');
  const [lang, setLang] = useState('python');
  const [img, setImg] = useState('');

  const backendURL = 'http://127.0.0.1:5000';



  const generate = async () => {
    if (!code.trim()) {
      alert('Code cannot be blank!');
      return;
    }

    try {
      await axios.post(`${backendURL}/execute`, { code, lang });
      setImg(`${backendURL}/output/visualization.png?t=${Date.now()}`);
    } catch (error) {
      if (error.response && error.response.data && error.response.data.message) {
        alert(error.response.data.message);
      } else {
        alert('Something went wrong!');
      }
    }
  }


  return (
    <div>
      <h1>Visualization App</h1>

      <select onChange={(e) => setLang(e.target.value)}>
        <option value="python">Python</option>
        <option value="r">R</option>
      </select>

      <textarea rows="10" cols="50" onChange={(e) => setCode(e.target.value)} />

      <button onClick={generate}>Generate Visualization</button>

      {img && <img src={img} alt="Visualization" />}
    </div>
  );
}

export default App;
